// Application schema (Drizzle, SQLite/libSQL). Adapted from docs/kit/schema.sql.
// Better Auth tables live in ./auth-schema.ts (generated by `npm run auth:generate`).
// Constraints help integrity; they do NOT replace tenant + owner checks in every query (src/server/dal).
import { sql } from "drizzle-orm";
import { check, foreignKey, index, integer, primaryKey, sqliteTable, text, unique, uniqueIndex } from "drizzle-orm/sqlite-core";

const ms = (name: string) => integer(name).notNull();

export const appUsers = sqliteTable(
  "app_users",
  {
    id: text("id").primaryKey().notNull(), // = Better Auth user.id
    isGuest: integer("is_guest").notNull().default(0),
    createdAt: ms("created_at"),
    lastSeenAt: ms("last_seen_at"),
  },
  (t) => [check("app_users_guest", sql`${t.isGuest} IN (0,1)`)],
);

export const tenants = sqliteTable(
  "tenants",
  {
    id: text("id").primaryKey().notNull(),
    slug: text("slug").notNull().unique(),
    name: text("name").notNull(),
    status: text("status").notNull().default("active"),
    isPublic: integer("is_public").notNull().default(0),
    maxActiveSessions: integer("max_active_sessions").notNull().default(2),
    createdAt: ms("created_at"),
  },
  (t) => [
    check("tenants_status", sql`${t.status} IN ('active','suspended')`),
    check("tenants_public", sql`${t.isPublic} IN (0,1)`),
    check("tenants_max_sessions", sql`${t.maxActiveSessions} BETWEEN 0 AND 100`),
  ],
);

export const memberships = sqliteTable(
  "memberships",
  {
    tenantId: text("tenant_id").notNull().references(() => tenants.id, { onDelete: "cascade" }),
    userId: text("user_id").notNull().references(() => appUsers.id, { onDelete: "cascade" }),
    role: text("role").notNull(),
    createdAt: ms("created_at"),
  },
  (t) => [primaryKey({ columns: [t.tenantId, t.userId] }), check("memberships_role", sql`${t.role} IN ('owner','admin','player')`)],
);

export const episodeVersions = sqliteTable(
  "episode_versions",
  {
    episodeId: text("episode_id").notNull(),
    version: integer("version").notNull(),
    contentHash: text("content_hash").notNull(),
    contentJson: text("content_json").notNull(),
    publishedAt: ms("published_at"),
  },
  (t) => [
    primaryKey({ columns: [t.episodeId, t.version] }),
    check("episode_version_pos", sql`${t.version} > 0`),
    check("episode_json", sql`json_valid(${t.contentJson})`),
  ],
);

export const runs = sqliteTable(
  "runs",
  {
    id: text("id").primaryKey().notNull(),
    tenantId: text("tenant_id").notNull(),
    ownerUserId: text("owner_user_id").notNull(),
    episodeId: text("episode_id").notNull(),
    episodeVersion: integer("episode_version").notNull(),
    revision: integer("revision").notNull().default(0),
    status: text("status").notNull().default("active"),
    stateJson: text("state_json").notNull(),
    createdAt: ms("created_at"),
    updatedAt: ms("updated_at"),
    expiresAt: ms("expires_at"),
  },
  (t) => [
    unique("runs_tenant_id").on(t.tenantId, t.id),
    check("runs_revision", sql`${t.revision} >= 0`),
    check("runs_status", sql`${t.status} IN ('active','finished','deleting')`),
    check("runs_state_json", sql`json_valid(${t.stateJson})`),
    foreignKey({ columns: [t.tenantId, t.ownerUserId], foreignColumns: [memberships.tenantId, memberships.userId] }).onDelete("cascade"),
    foreignKey({ columns: [t.episodeId, t.episodeVersion], foreignColumns: [episodeVersions.episodeId, episodeVersions.version] }),
    index("runs_owner").on(t.tenantId, t.ownerUserId, t.updatedAt),
    index("runs_expiry").on(t.expiresAt),
  ],
);

const runFk = (t: { tenantId: ReturnType<typeof text>; runId: ReturnType<typeof text> }) =>
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  foreignKey({ columns: [t.tenantId as any, t.runId as any], foreignColumns: [runs.tenantId, runs.id] }).onDelete("cascade");

export const runEvents = sqliteTable(
  "run_events",
  {
    tenantId: text("tenant_id").notNull(),
    runId: text("run_id").notNull(),
    revision: integer("revision").notNull(),
    type: text("type").notNull(),
    payloadJson: text("payload_json").notNull(),
    actorUserId: text("actor_user_id").notNull(),
    channel: text("channel").notNull(),
    createdAt: ms("created_at"),
  },
  (t) => [
    primaryKey({ columns: [t.tenantId, t.runId, t.revision] }),
    check("run_events_revision", sql`${t.revision} > 0`),
    check("run_events_json", sql`json_valid(${t.payloadJson})`),
    check("run_events_channel", sql`${t.channel} IN ('ui','tool','ending-confirmed','rehearsal')`),
    runFk(t),
    foreignKey({ columns: [t.tenantId, t.actorUserId], foreignColumns: [memberships.tenantId, memberships.userId] }),
  ],
);

export const commandReceipts = sqliteTable(
  "command_receipts",
  {
    tenantId: text("tenant_id").notNull(),
    runId: text("run_id").notNull(),
    commandId: text("command_id").notNull(),
    actorUserId: text("actor_user_id").notNull(),
    requestHash: text("request_hash").notNull(),
    resultJson: text("result_json").notNull(),
    createdAt: ms("created_at"),
  },
  (t) => [
    primaryKey({ columns: [t.tenantId, t.runId, t.commandId] }),
    check("receipts_json", sql`json_valid(${t.resultJson})`),
    runFk(t),
    foreignKey({ columns: [t.tenantId, t.actorUserId], foreignColumns: [memberships.tenantId, memberships.userId] }),
  ],
);

export const characterMemories = sqliteTable(
  "character_memories",
  {
    tenantId: text("tenant_id").notNull(),
    runId: text("run_id").notNull(),
    characterId: text("character_id").notNull(),
    generation: integer("generation").notNull().default(1),
    observedRevision: integer("observed_revision").notNull(),
    factsJson: text("facts_json").notNull(),
    summary: text("summary").notNull().default(""),
    updatedAt: ms("updated_at"),
  },
  (t) => [
    primaryKey({ columns: [t.tenantId, t.runId, t.characterId] }),
    check("memories_character", sql`${t.characterId} IN ('jeanne','malik')`),
    check("memories_generation", sql`${t.generation} > 0`),
    check("memories_json", sql`json_valid(${t.factsJson})`),
    runFk(t),
  ],
);

export const napsterBindings = sqliteTable(
  "napster_bindings",
  {
    tenantId: text("tenant_id").notNull(),
    runId: text("run_id").notNull(),
    characterId: text("character_id").notNull(),
    generation: integer("generation").notNull(),
    externalClientId: text("external_client_id").notNull().unique(),
    agentId: text("agent_id").notNull(),
    createdAt: ms("created_at"),
  },
  (t) => [
    primaryKey({ columns: [t.tenantId, t.runId, t.characterId, t.generation] }),
    check("bindings_character", sql`${t.characterId} IN ('jeanne','malik','pixo')`),
    check("bindings_ecid_len", sql`length(${t.externalClientId}) BETWEEN 1 AND 32`),
    runFk(t),
  ],
);

export const conversationLeases = sqliteTable(
  "conversation_leases",
  {
    id: text("id").primaryKey().notNull(),
    tenantId: text("tenant_id").notNull(),
    runId: text("run_id").notNull(),
    userId: text("user_id").notNull(),
    providerScope: text("provider_scope").notNull(),
    characterId: text("character_id").notNull(),
    externalClientId: text("external_client_id").notNull(),
    /** Locale of the session: selects the agent and the language of tool outputs. */
    locale: text("locale").notNull().default("fr"),
    connectionId: text("connection_id").unique(),
    status: text("status").notNull(),
    statusReason: text("status_reason"),
    heartbeatAt: ms("heartbeat_at"),
    expiresAt: ms("expires_at"),
    createdAt: ms("created_at"),
    updatedAt: ms("updated_at"),
  },
  (t) => [
    check("leases_character", sql`${t.characterId} IN ('jeanne','malik','pixo')`),
    check("leases_status", sql`${t.status} IN ('reserved','active','closing','uncertain','closed','failed')`),
    check("leases_locale", sql`${t.locale} IN ('fr','en')`),
    runFk(t),
    // One open session per run and CHARACTER: both characters may be connected (instant era switch).
    uniqueIndex("one_open_lease_per_run_character").on(t.tenantId, t.runId, t.characterId).where(sql`status IN ('reserved','active','closing','uncertain')`),
    index("leases_capacity").on(t.providerScope, t.status, t.expiresAt),
  ],
);

/**
 * The player's own turns in a live conversation (final transcript or typed line), reduced to
 * server-computed indicators. NEVER the text: only a hash, what it mentions, a parsed seat or place.
 * A character's tool call that records something "shared by the player" must be backed by one.
 */
export const playerTurns = sqliteTable(
  "player_turns",
  {
    tenantId: text("tenant_id").notNull(),
    runId: text("run_id").notNull(),
    leaseId: text("lease_id").notNull(),
    itemId: text("item_id").notNull(),
    at: ms("at"),
    textHash: text("text_hash").notNull(),
    mentionsNote: integer("mentions_note").notNull().default(0),
    mentionsWater: integer("mentions_water").notNull().default(0),
    mentionsReport: integer("mentions_report").notNull().default(0),
    mentionsFuture: integer("mentions_future").notNull().default(0),
    seat: text("seat"),
    location: text("location"),
  },
  (t) => [primaryKey({ columns: [t.leaseId, t.itemId] }), runFk(t), index("player_turns_recent").on(t.leaseId, t.at)],
);

export const providerBudgets = sqliteTable("provider_budgets", {
  scope: text("scope").primaryKey().notNull(),
  nextAllowedAt: ms("next_allowed_at"),
  updatedAt: ms("updated_at"),
});

export const jobs = sqliteTable(
  "jobs",
  {
    id: text("id").primaryKey().notNull(),
    tenantId: text("tenant_id").notNull(),
    runId: text("run_id").notNull(),
    kind: text("kind").notNull(),
    dedupeKey: text("dedupe_key").notNull(),
    status: text("status").notNull(),
    payloadJson: text("payload_json").notNull(),
    resultJson: text("result_json"),
    attempts: integer("attempts").notNull().default(0),
    nextAttemptAt: ms("next_attempt_at"),
    leaseOwner: text("lease_owner"),
    leaseUntil: integer("lease_until"),
    createdAt: ms("created_at"),
    updatedAt: ms("updated_at"),
  },
  (t) => [
    check("jobs_kind", sql`${t.kind} IN ('recording','cleanup','delete_media')`),
    check("jobs_status", sql`${t.status} IN ('pending','running','uncertain','completed','failed','cancelled')`),
    check("jobs_payload", sql`json_valid(${t.payloadJson})`),
    check("jobs_result", sql`${t.resultJson} IS NULL OR json_valid(${t.resultJson})`),
    check("jobs_attempts", sql`${t.attempts} >= 0`),
    unique("jobs_dedupe").on(t.tenantId, t.runId, t.kind, t.dedupeKey),
    runFk(t),
    index("jobs_ready").on(t.status, t.nextAttemptAt, t.leaseUntil),
  ],
);

/** One-time, short-lived confirmation for the final choice (UI channel only). Not in the kit schema. */
export const endingIntents = sqliteTable(
  "ending_intents",
  {
    tokenHash: text("token_hash").primaryKey().notNull(),
    tenantId: text("tenant_id").notNull(),
    runId: text("run_id").notNull(),
    userId: text("user_id").notNull(),
    ending: text("ending").notNull(),
    revision: integer("revision").notNull(),
    expiresAt: ms("expires_at"),
    consumedAt: integer("consumed_at"),
    createdAt: ms("created_at"),
  },
  (t) => [check("ending_intents_ending", sql`${t.ending} IN ('public_cut','sealed_archive','broken_promise')`), runFk(t)],
);

export const invitations = sqliteTable(
  "invitations",
  {
    id: text("id").primaryKey().notNull(),
    tenantId: text("tenant_id").notNull().references(() => tenants.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull().unique(),
    emailNormalized: text("email_normalized").notNull(),
    role: text("role").notNull(),
    createdBy: text("created_by"),
    expiresAt: ms("expires_at"),
    consumedAt: integer("consumed_at"),
    consumedBy: text("consumed_by"),
    createdAt: ms("created_at"),
  },
  // 'owner' is allowed only for the local bootstrap invitation (scripts/ops-bootstrap-owner.ts).
  (t) => [check("invitations_role", sql`${t.role} IN ('owner','admin','player')`)],
);

export const auditEvents = sqliteTable(
  "audit_events",
  {
    id: text("id").primaryKey().notNull(),
    tenantId: text("tenant_id").notNull().references(() => tenants.id, { onDelete: "cascade" }),
    actorRef: text("actor_ref"),
    eventType: text("event_type").notNull(),
    metadataJson: text("metadata_json").notNull(),
    createdAt: ms("created_at"),
  },
  (t) => [check("audit_json", sql`json_valid(${t.metadataJson})`), index("audit_tenant_date").on(t.tenantId, t.createdAt)],
);
